    const foco = a && el.contains(a) ? { id: a.id, nome: a.name, form: a.form && a.form.dataset.form, ini: (() => { try { return a.selectionStart; } catch (e) { return null; } })(), fim: (() => { try { return a.selectionEnd; } catch (e) { return null; } })() } : null;
